"""Автономный просмотр типизированных предпосылок и контрольных заключений."""
import json


def markdown(data):
    s,e=data["sealed"],data["evaluation"]
    lines=["# Типизированные эмпирические утверждения: малый источниковый контроль", "",
        "**Инженерный контроль: 22/22 ожидаемых решений; упрощённая база p<0.05 — 14/22. Новых научных предсказаний: 0. Критерий предсказания последующей статьи не достигнут.**", "",
        "## Объём опыта", "",
        "Все пять утверждённых снимков проверены по хешам и происхождению. Вручную типизирован небольшой явно выбранный поднабор: 13 коэффициентов из таблиц 5–6 и их сносок PMC8775386, 3 коэффициента метарегрессии из таблицы 3 PMC7789349. Остальные три статьи на этом шаге не типизированы. Константы регрессий исключены. Карты не пересобирались.", "",
        "Шесть дополнительных случаев искусственно испорчены: другой показатель, группа, дизайн, набор ковариат, отсутствующий p и подмена коэффициента отношением рисков. Они не являются утверждениями источников.", "",
        "## Что теперь хранится явно", "",
        "Каждый числовой факт содержит исследование, анализ, группу, дизайн, временной контекст, показатель и его шкалу, ковариаты, размер выборки, предиктор, вид коэффициента, точное исходное число, p, интервал, кодирование и координаты источника. Неизвестные единицы коэффициента сохранены как неизвестные. Плазма относится к измеренному биомаркеру, а не автоматически задаёт единицы коэффициента.", "",
        "Порог проверки — отдельная предпосылка, привязанная к тому же анализу и контексту. Коэффициент, p и политика тестирования используются совместно. Результат не наследуется другой группой или исходом. При восстановлении направления коэффициента не создаются причинный вывод, числовой прогноз или вывод о будущем когнитивном снижении.", "",
        "## Решения", "", "| Поднабор | Случаев | Оператор: верные решения | База p<0.05 |", "|---|---:|---:|---:|"]
    for kind,label in [("source_numeric_reconstruction","Реальные числовые строки"),("source_derived_synthetic_negative","Искусственные отрицательные контроли")]:
        op=[r for r in e["operator"]["rows"] if r["kind"]==kind]
        baseline=[r for r in e["nominal_baseline"]["rows"] if r["kind"]==kind]
        lines.append(f'| {label} | {len(op)} | {sum(r["matched"] for r in op)} | {sum(r["matched"] for r in baseline)} |')
    lines += ["", "Оператор получил восемь результатов, проходящих соответствующий порог, семь не проходящих его и семь отказов: одна несогласованная исходная строка плюс шесть искусственных контролей. Не прошедший порог результат не означает «связи нет» или «эффект равен нулю».", "",
        "## Наиболее полезные случаи", "",
        "1. Ночной сон >450 минут и TNF-α в полной выборке: B=0.230, p=0.04. Номинальный порог .05 пройден, указанный в источнике Bonferroni-порог .017 — нет. Положительный 95% CI не заменяет более строгий порог множественной проверки.",
        "2. Красное мясо и TNF-α: B=−0.102, CI (−0.077; 0.282). Коэффициент не попадает в собственный приведённый интервал. Исходная строка сохранена; оператор отказывается вместо самостоятельного исправления числа.",
        "3. В подгруппе MCI связь длинного сна и TNF-α имеет p=0.2 в сноске. Discussion утверждает значимость после поправки. Это расхождение статистической таблицы и авторского текста; авторскую формулировку не переносим как установленный факт.",
        "4. Physical activity и IL-6: B=−0.538, p=0.001. В Methods отсутствие активности кодируется 1, наличие — 0, но строка таблицы названа Physical activity. Отрицательный знак сохранён на опубликованной шкале; вывод «неактивность снижает воспаление» заблокирован из-за неоднозначности кодирования.",
        "5. В метарегрессии исследований возраст имеет p=.171, период исследования p=.011, диагностические критерии p=.145. Вывод относится к метарегрессии и опубликованной шкале lnhr; его нельзя переносить на причинный или индивидуальный возрастной риск.", "",
        "## Защита от подглядывания", "",
        "Процесс фиксации получает только inputs.json. Авторские заключения из Results/Discussion находятся в отдельном hidden-controls.json. Для порога метарегрессии из соответствующего абзаца передан только точный фрагмент p>0.05, а не фразы с выводом. Оценщик открывает контроли только после проверки неизменяемой фиксации и версии кода. Целевая PMC10000452 не загружалась ни на одном этапе этой итерации.", "",
        "Контроли подготовлены Codex, который уже прочитал источники; это не слепой опыт и не независимая экспертная разметка. Ожидаемые решения проверяют интерпретацию заданных чисел и отказы, а не обучение неизвестному научному правилу. Восстановленные сводки уже следуют из исходных таблиц и не являются новым эмпирическим знанием.", "",
        f'Запуск: `{s["run_id"]}`. Оценка: `{e["evaluation_id"]}`. Точная реализация, исходные входы, контроли, квитанции, хеши и разбор всех случаев сохранены.', "",
        "## Следующий шаг", "",
        "Теперь нужна следующая группа операторов — сопоставление и перенос между типизированными эмпирическими утверждениями разных исследований с доказанной совместимостью контекстов. Для неё надо отделить первичные исследования от пересказов в обзорах и явные условия применимости от статистических значений. Эти 16 строк недостаточны для обучения повторяющимся независимым научным закономерностям.", "",
        "Перед любым новым полным прогнозом проверить оператор на скрытых заключениях из другого исследования и трудных несовместимых парах, затем заморозить его. Научный успех требует нового утверждения, отсутствующего в обучении, зафиксированного до проверки и подтверждённого независимым последующим источником. Текущий контроль к такому успеху не приравнивается.", "",
        "Пройдено 67 Python-тестов. Модельных и сетевых вызовов: 0. Подписи RU/EN подготовлены Codex. Расход токенов Codex не измерен. GOLD, старые карты и прогнозы сохранены. Изменения находятся в самостоятельном CLI; перезапуск сервисов не требуется. Требуется экспертная научная проверка."]
    return "\n".join(lines)+"\n"


def render(data):
    encoded=json.dumps(data,ensure_ascii=False,allow_nan=False,separators=(",",":"))
    return TEMPLATE.replace("__DATA__",encoded.replace("<","\\u003c").replace("\u2028","\\u2028").replace("\u2029","\\u2029"))


TEMPLATE=r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Эмпирические утверждения: контроль операторов</title>
<style>body{font:16px/1.55 system-ui;color:#16273d;background:#f3f6fb;max-width:1260px;margin:auto;padding:26px}h1{font-size:29px}button,select,a{font:inherit}button,select,.link{padding:9px 14px;border:1px solid #8d9db2;border-radius:8px;color:#16273d;background:white}button,.link{cursor:pointer}.link{text-decoration:none}button:hover,.link:hover{background:#e6eefb}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #2563eb}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.card{padding:18px;border:1px solid #cbd5e1;background:white;border-radius:10px;margin:16px 0}.notice{border-left:5px solid #b45309}table{border-collapse:collapse;width:100%;background:white}td,th{padding:11px;text-align:left;border:1px solid #cbd5e1}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto}mark{background:#ffeda8}.premises{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.premise{background:#edf3fb;border:1px solid #b8c8de;border-radius:8px;padding:15px}.arrow{text-align:center;font-size:26px}.result{border:2px solid #6686b0;border-radius:8px;padding:15px}#fragment{max-height:260px}@media(max-width:700px){.premises{grid-template-columns:1fr}}</style>
<h1 id="heading"></h1><div class="toolbar"><button id="ru">Русский</button><button id="en">English</button><a class="link" href="report.ru.md">Отчёт / Report</a><a class="link" href="inputs.json">Входы / Inputs</a><a class="link" href="predictions.json">Решения / Decisions</a><a class="link" href="evaluation.json">Оценка / Evaluation</a></div>
<div class="card notice" id="notice"></div><div class="card" id="summary"></div><table id="metrics"></table><div class="card" id="caution"></div>
<div class="toolbar"><label id="filter-label" for="filter"></label><select id="filter"><option value="all">Все / All</option><option value="real">Исходные строки / Source rows</option><option value="negative">Искусственные контроли / Synthetic controls</option><option value="issues">Расхождения и кодирование / Discrepancies and coding</option></select></div>
<table><thead><tr><th id="case-label"></th><th id="decision-label"></th><th id="score-label"></th><th></th></tr></thead><tbody id="rows"></tbody></table>
<div class="card" id="detail" hidden><h2 id="detail-heading"></h2><div class="premises"><div class="premise" id="coefficient"></div><div class="premise" id="pvalue"></div><div class="premise" id="threshold"></div></div><div class="arrow">↓</div><div class="result" id="conclusion"></div><p id="context"></p><p id="control-note"></p><div class="toolbar" id="proofs"></div><h3 id="fragment-heading"></h3><pre id="fragment"></pre><details><summary id="source-label"></summary><pre id="source"></pre></details><details><summary id="semantic-label"></summary><pre id="semantic"></pre></details></div>
<details class="card"><summary id="versions-label"></summary><pre id="versions"></pre></details>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let lang='ru';const t=(r,e)=>lang==='ru'?r:e;
function row(values){const r=document.createElement('tr');for(const v of values){const c=document.createElement('td');c.textContent=v;r.append(c)}return r}
const status=s=>({threshold_met:t('Порог пройден','Threshold met'),threshold_not_met:t('Порог не пройден; отсутствие эффекта не доказано','Threshold not met; absence of effect not established'),abstain:t('Отказ: несовместимые или неполные основания','Abstain: incompatible or incomplete premises')}[s]);
const dir=d=>d==='negative'?t('Отрицательный знак на опубликованной шкале','Negative on the reported scale'):d==='positive'?t('Положительный знак на опубликованной шкале','Positive on the reported scale'):t('Направленный вывод не сделан','No directional conclusion');
function excerpt(key){const p=D.evidence[key],s=D.sources[p.article_id],c=Array.from(s.text);const txt=c.slice(p.start,p.end).join('');$('fragment').textContent=txt;$('fragment').dataset.evidence=key;const mark=document.createElement('mark');mark.textContent=txt;$('source').replaceChildren(document.createTextNode(c.slice(0,p.start).join('')),mark,document.createTextNode(c.slice(p.end).join('')))}
function inspect(c){$('detail').hidden=false;const e=c.effect,p=c.policy,r=D.sealed.results.find(x=>x.case_id===e.id),ctrl=D.controls.controls.find(x=>x.case_id===e.id);$('coefficient').textContent=t('Коэффициент: ','Coefficient: ')+e.coefficient+t(' · единицы: неизвестны',' · units: unspecified')+'\n'+t('95% интервал: ','95% interval: ')+(e.interval?.join(' … ')||t('не приведён','not reported'));$('pvalue').textContent=t('Соответствующий p: ','Matched p: ')+(e.p_value??t('отсутствует','missing'));$('threshold').textContent='p < '+p.alpha+'\n'+p.correction+'\n'+t('Только тот же контекст','Identical context required');$('conclusion').textContent=status(r.status)+' · '+dir(r.direction)+(r.reason?' · '+r.reason:'')+(r.real_world_direction===null?t(' · Интерпретация реального направления не утверждается',' · No real-world directional interpretation is asserted'):'');$('context').textContent=JSON.stringify(r.context);$('control-note').textContent=t('Контроль Codex: ','Codex control: ')+ctrl.kind+' · '+ctrl.source_claim_relation+t('. Это восстановление сводки, не новое научное предсказание.','. This reconstructs a summary; it is not a novel scientific prediction.');$('semantic').textContent=JSON.stringify({inputs:c,decision:r,control:ctrl},null,2);$('proofs').replaceChildren();for(const [kind,keys] of [[t('Предпосылка','Premise'),r.evidence_ids],[t('Скрытый контроль','Withheld control'),ctrl.evidence]])for(const key of [...new Set(keys)]){const b=document.createElement('button');b.textContent=kind+' · '+key;b.onclick=()=>excerpt(key);$('proofs').append(b)}$('proofs').querySelector('button')?.click()}
function render(){document.documentElement.lang=lang;$('heading').textContent=t('Типизированные эмпирические утверждения: контроль операторов','Typed empirical statements: operator checks');$('notice').textContent=t('Инженерная проверка: 22/22. Новых научных предсказаний: 0. Критерий предсказания будущей статьи ещё не достигнут.','Engineering checks: 22/22. Novel scientific predictions: 0. The future-article prediction criterion is not yet met.');$('summary').textContent=t('Проверены хеши всех пяти источников. Типизированы 16 числовых результатов из двух статей; добавлены 6 искусственных отрицательных контролей. Получены 8 решений «порог пройден», 7 «не пройден» и 7 отказов.','All five source hashes are verified. Typed subset: 16 numeric results from two articles plus 6 synthetic negative controls. Outcomes: 8 threshold-met decisions, 7 threshold-not-met decisions and 7 abstentions.');$('caution').textContent=t('Оператор восстанавливает статистическое заключение из коэффициента, p и правила проверки. Он не научился предсказывать неизвестные результаты. Контроли размечены Codex и требуют экспертной проверки. Причинность, перенос между группами и предсказание будущего из поперечного исследования запрещены.','The operator reconstructs a statistical conclusion from a coefficient, p and test policy. It has not learned to predict unknown findings. Controls are annotated by Codex and require expert review. Causality, population transfer and future-outcome prediction from cross-sectional data are prohibited.');
$('metrics').replaceChildren(row([t('Набор','Subset'),t('Случаев','Cases'),t('Оператор: ожидаемые решения','Operator: expected decisions'),t('База p<0.05','p<0.05 baseline')]));for(const [kind,label] of [['source_numeric_reconstruction',t('Реальные строки','Source rows')],['source_derived_synthetic_negative',t('Искусственные контроли','Synthetic controls')]]){const op=D.evaluation.operator.rows.filter(x=>x.kind===kind),base=D.evaluation.nominal_baseline.rows.filter(x=>x.kind===kind);$('metrics').append(row([label,op.length,op.filter(x=>x.matched).length,base.filter(x=>x.matched).length]))}
for(const [id,r,e] of [['filter-label','Показать','Show'],['case-label','Случай','Case'],['decision-label','Решение','Decision'],['score-label','Контроль','Check'],['detail-heading','Совместные предпосылки и вывод','Joint premises and conclusion'],['fragment-heading','Точный исходный фрагмент','Exact source excerpt'],['source-label','Полный источник с выделением','Full source with highlight'],['semantic-label','Типизированная семантика и контроль','Typed semantics and control'],['versions-label','Версии, границы опыта и квитанции','Versions, scope and receipts']])$(id).textContent=t(r,e);
const filter=$('filter').value;$('rows').replaceChildren();$('detail').hidden=true;for(const c of D.inputs.cases){const id=c.effect.id,label=D.inputs.labels[id],ctrl=D.controls.controls.find(x=>x.case_id===id),res=D.sealed.results.find(x=>x.case_id===id),check=D.evaluation.operator.rows.find(x=>x.case_id===id);if(filter==='real'&&label.kind!=='source_numeric_reconstruction'||filter==='negative'&&label.kind!=='source_derived_synthetic_negative'||filter==='issues'&&!['nominal_only_after_adjustment','reported_coefficient_interval_inconsistency','coding_needs_clarification','disagrees_with_discussion'].includes(ctrl.source_claim_relation))continue;const r=row([id+' · '+label[lang],status(res.status),check.matched?t('Ожидаемое решение получено','Expected decision obtained'):t('Расхождение','Mismatch')]),cell=document.createElement('td'),b=document.createElement('button');b.textContent=t('Разобрать','Inspect');b.onclick=()=>inspect(c);cell.append(b);r.append(cell);$('rows').append(r)}$('versions').textContent=JSON.stringify({binding:D.sealed.binding,evaluation:D.evaluation.binding,receipts:D.receipts,preparation:D.preparation,metadata:D.inputs.metadata},null,2)}
$('ru').onclick=()=>{lang='ru';render()};$('en').onclick=()=>{lang='en';render()};$('filter').onchange=render;render();
</script></html>'''
